use maho_rpc::host_runner::*;
#[tokio::test]async fn absent_endpoint_reports_refused_status_and_unknown_owner_stop(){let temp=tempfile::tempdir().unwrap();let socket=temp.path().join("absent.sock");let socket=socket.to_str().unwrap();let status=status_outcome(socket,temp.path(),true).await.unwrap();assert_eq!(status.exit_code,HOST_EXIT_REFUSED);assert_eq!(status.payload["reachable"],false);let stop=stop_outcome(socket,temp.path(),false,false).await.unwrap();assert_eq!(stop.exit_code,HOST_EXIT_REFUSED);assert_eq!(stop.payload["reason"],"unknown_owner");assert_eq!(stop.payload["sessions"]["total"],0);assert!(stop.payload["host"].is_null());}
